#!/usr/bin/env python3
"""Canonical legacy MOVHLPS/MOVLHPS with independent half selection."""
import hashlib,json,pathlib,random,subprocess
R=pathlib.Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();out=R/'generated/sse/legacy-halfmove-reference';out.mkdir(exist_ok=True);rng=random.Random(0x25034);requests=[];specs=[]
for high in range(2):
 for i in range(4096):
  control=0x1f80|((i&3)<<13)|(0x40 if i&4 else 0)|(0x8000 if i&8 else 0)|(i%64);flags=rng.getrandbits(32)&0x8d5;a=[rng.getrandbits(32) for _ in range(8)];b=[rng.getrandbits(32) for _ in range(8)]
  if i<128:a[:4]=[1<<(i%32) if k==i//32 else 0 for k in range(4)];b[:4]=[x^0xffffffff for x in a[:4]]
  requests.append(f'{high} {control:x} {flags:x} '+' '.join(f'{x:x}' for x in a+b)+'\n');specs.append((high,control,flags,a,b))
text=''.join(requests);(out/'requests.txt').write_text(text);c=R/'tests/legacy_halfmove_oracle.c';exe=out/'reference';sdk=subprocess.check_output(['xcrun','--sdk','macosx','--show-sdk-path'],text=True).strip();subprocess.run(['clang','-target','x86_64-apple-macos12','-isysroot',sdk,'-std=c11','-O2','-mavx','-mno-red-zone','-Wall','-Wextra','-Werror',str(c),'-o',str(exe)],check=True);run=subprocess.run([str(exe)],input=text,capture_output=True,text=True,timeout=60);assert not run.returncode and not run.stderr,(run.returncode,run.stderr);lines=run.stdout.splitlines();assert len(lines)==len(specs)
for spec,line in zip(specs,lines):
 high,control,flags,a,b=spec;want=a[:];want[2 if high else 0:4 if high else 2]=b[0 if high else 2:2 if high else 4];assert [int(x,16) for x in line.split()]==[control,flags]+want,(spec,line,want)
(out/'reference.txt').write_text(run.stdout);assembly=subprocess.check_output(['otool','-tvV',str(exe)],text=True);(out/'disassembly.txt').write_text(assembly);assert assembly.count('\tmovhlps\t')==1 and assembly.count('\tmovlhps\t')==1 and '\tvmovhlps\t' not in assembly and '\tvmovlhps\t' not in assembly;report={'pass':True,'cases':len(specs),'directions':2,'source_sha256':{str(p.relative_to(R)):sha(p) for p in [c,pathlib.Path(__file__).resolve()]},'requests_sha256':sha(out/'requests.txt'),'results_sha256':sha(out/'reference.txt'),'binary_sha256':sha(exe),'scope':'Fresh legacy MOVHLPS/MOVLHPS Rosetta reference,128 bit-basis plus3968 random vectors per direction. Exact half selection, masked MXCSR/arithmetic flags/source/YMM upper preservation. Not physical Intel/fullDLL/gameplay proof.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS:',len(specs),'canonical legacy half-register move checks')
